var import_obsidian = require("obsidian");
var DEBUG_LOG_FILE = "remote-ssh-debug.log";
var MAX_LOG_LINES = 500;
var FLUSH_INTERVAL_MS = 1e3;
var BUFFER_FLUSH_THRESHOLD = 20;
var VaultLogger = class {
  constructor(app, manifest) {
    this.app = app;
    this.manifest = manifest;
    this.enabled = false;
    this.buffer = [];
    this.timer = null;
    this.logFile = null;
  }
  async initialize() {
    this.enabled = true;
    this.logFile = this.app.vault.getAbstractFileByPath(DEBUG_LOG_FILE);
    if (!this.logFile) {
      try {
        this.logFile = await this.app.vault.create(DEBUG_LOG_FILE, "");
      } catch {
        this.enabled = false;
        return false;
      }
    }
    await this.rotateIfNeeded();
    this.timer = setInterval(() => this.flush(), FLUSH_INTERVAL_MS);
    this.log("INFO", "=== Remote SSH Plugin starting ===", {
      platform: import_obsidian.Platform.isMobileApp ? "mobile" : "desktop",
      version: this.manifest.version
    });
    return true;
  }
  log(level, message, meta) {
    if (!this.enabled) return;
    const line = `[${(/* @__PURE__ */ new Date()).toISOString()}] [${level}] ${message}${meta ? ` ${JSON.stringify(meta)}` : ""}`;
    this.buffer.push(line);
    if (this.buffer.length >= BUFFER_FLUSH_THRESHOLD) {
      void this.flush();
    }
  }
  async flush() {
    if (!this.enabled || !this.logFile || this.buffer.length === 0) return;
    const text = `${this.buffer.splice(0, this.buffer.length).join("\n")}
`;
    try {
      await this.app.vault.append(this.logFile, text);
      await this.rotateIfNeeded();
    } catch (e) {
      console.error("[VaultLogger] flush failed:", e);
    }
  }
  async rotateIfNeeded() {
    if (!this.logFile) return;
    try {
      const content = await this.app.vault.read(this.logFile);
      const lines = content.split("\n").filter((l) => l.trim());
      if (lines.length > MAX_LOG_LINES) {
        const keep = lines.slice(-Math.floor(MAX_LOG_LINES * 0.5));
        await this.app.vault.modify(this.logFile, `${keep.join("\n")}
`);
      }
    } catch {
    }
  }
  destroy() {
    if (this.timer) clearInterval(this.timer);
    void this.flush();
    this.enabled = false;
  }
};

